import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"粘包与帧定界","description":"","frontmatter":{"title":"粘包与帧定界","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/message-framing.md","filePath":"cs/message-framing.md","lastUpdated":1789023840000}'),h={name:"cs/message-framing.md"};function m(_,a,P,f,u,T){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="粘包与帧定界" tabindex="-1">粘包与帧定界 <a class="header-anchor" href="#粘包与帧定界" aria-label="Permalink to &quot;粘包与帧定界&quot;">​</a></h1><div class="epigraph"><p>TCP 是字节流，两次 `write` 可并成一次 `read`；应用必须自己定界：长度前缀、分隔符或自描述编码。</p><footer>—— 据 RFC 9293 字节流；Stevens UNP；Protobuf/gRPC 帧对照整理</footer></div><p><a href="/cs/serialization-protobuf">序列化</a> 产出消息。<a href="/cs/reactor-proactor">Reactor</a> 一次可读任意字节。<a href="/cs/c10k-concurrency">上一课</a> 不保证消息边界。缺口是<strong>成帧</strong>：粘包、拆包、缓冲。本课不把心跳写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UDP 有报文边界（仍可能丢/乱序）。TCP 无。JSON 无长度时要括号配对，危险。常见：4 字节长度 + 体；WebSocket 已有帧；gRPC 有 5 字节前缀；HTTP/1.1 用 Content-Length/chunked。TSO 把大缓冲切开，接收 GRO 再粘，应用仍要定界。SSH 与 TLS 记录层自己成帧。</p><p>不要用 <code>sleep</code> 当定界。</p><p><span class="marginnote">UNP 强调。本课不发明私有协议细节。</span></p><h3 id="字节流无消息" tabindex="-1">字节流无消息 <a class="header-anchor" href="#字节流无消息" aria-label="Permalink to &quot;字节流无消息&quot;">​</a></h3><p>长度前缀或记录层定界。sleep 不是帧。最大长度要帽。SCTP/UDP 有边界是对照不是 TCP 的性质。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三种定界。画：读循环 → 缓冲 → 切消息 → handler。与线路码逗号对齐同构，一层 PHY，一层应用。</p>',11)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BYTES%5B%22TCP%20%E5%AD%97%E8%8A%82%22%5D%20--%3E%20BUF%5B%22%E5%BA%94%E7%94%A8%E7%BC%93%E5%86%B2%22%5D%0A%20%20BUF%20--%3E%20LEN%5B%22%E9%95%BF%E5%BA%A6%E5%89%8D%E7%BC%80%E5%88%87%22%5D%0A%20%20BUF%20--%3E%20DELIM%5B%22%E5%88%86%E9%9A%94%E7%AC%A6%E5%88%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>部分读：非阻塞下必循环。最大长度要帽，防内存炸弹。QUIC 流有流内偏移，仍要应用帧若多消息。SCTP 消息边界是对照。PMTUD 不解决粘包。</p><p>安全：长度字段过大是 DoS。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ASN.1 TLV 的全部。心跳与超时是下一课。后课默认：字节流必须应用成帧。</p><p>把「一条 write 一条 read」当定理，在负载下必碎。</p><p>上一课留下的缺口在本课收口；「粘包与帧定界」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/heartbeat-timeout">心跳与超时</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCP 粘/拆包是正常。</li><li>长度、分隔或记录层定界。</li><li>读循环 + 上限缓冲。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293；UNP。</li></ul>',10))])}const S=i(h,[["render",m]]);export{C as __pageData,S as default};
